/// Checks if a dtype can represent a given integer value (i64 for wide range).
/// According to the problem:
/// - Unsigned ints represent 0 through max_uX
/// - Signed ints represent from min_iX through max_iX
/// - float and complex can represent any integer value
fn can_represent_value(dt: NumpyDType, value: i64) -> bool {
    match dt {
        // Unsigned: represent 0..=max
        NumpyDType::UInt8 => value >= 0 && value <= u8::MAX as i64,
        NumpyDType::UInt16 => value >= 0 && value <= u16::MAX as i64,
        NumpyDType::UInt32 => value >= 0 && value <= u32::MAX as i64,
        NumpyDType::UInt64 => value >= 0, // u64 max exceeds i64 max: only non-negative values. 
                                          // i64::MAX fits but values > i64::MAX won't be representable as i64 input anyway

        // Signed: represent min..=max
        NumpyDType::Int8 => value >= i8::MIN as i64 && value <= i8::MAX as i64,
        NumpyDType::Int16 => value >= i16::MIN as i64 && value <= i16::MAX as i64,
        NumpyDType::Int32 => value >= i32::MIN as i64 && value <= i32::MAX as i64,
        NumpyDType::Int64 => true, // i64 covers entire i64 range

        // Float and Complex: represent any integer value
        NumpyDType::Float16 | NumpyDType::Float32 | NumpyDType::Float64 |
        NumpyDType::Complex64 | NumpyDType::Complex128 => true,
    }
}

